/* Actionable care status and a return path to the same cycle-finish draft. */
(()=>{'use strict';
 const E=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const T=(en,ko)=>window.UKI18n?.language==='en'?en:ko,L=(en,ko)=>`<span data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(T(en,ko))}</span>`;
 const api=()=>window.MMCampaignEconomy,actor=()=>window.AccountParity?.account?.id||'local',units=g=>[...(g.fighters||[]),...(g.vehicles||[])],storageKey='underhive-cycle-finish-return';
 let currentDraft=null;
 function context(d=currentDraft){if(!d||d.actor!==actor())return null;const c=data.campaigns.find(row=>row.id===d.campaignId),g=data.gangs.find(row=>row.id===d.gangId);return c&&g&&api().participants(c).includes(g)?{c,g}:null;}
 function remember(d){currentDraft=d;try{sessionStorage.setItem(storageKey,JSON.stringify(d));}catch{}}
 function resume(){const ctx=context();if(ctx)open(ctx.c,ctx.g,currentDraft);}
 function bindReturn(bg,callback){const controller=new AbortController(),finish=()=>{controller.abort();closeModal();callback();};for(const id of ['modal-close','modal-cancel']){const button=bg.querySelector('#'+id);if(button)button.onclick=finish;}bg.addEventListener('click',event=>{if(event.target!==bg)return;event.preventDefault();event.stopImmediatePropagation();finish();},{capture:true,signal:controller.signal});window.addEventListener('keydown',event=>{if(event.key!=='Escape'||!bg.isConnected)return;event.preventDefault();event.stopImmediatePropagation();finish();},{capture:true,signal:controller.signal});return ()=>controller.abort();}
 function openUnit(fid){const ctx=context();if(!ctx)return;const f=units(ctx.g).find(row=>row.id===fid);closeModal();remember({...currentDraft,unitId:fid});data.selectedCampaign=ctx.c.id;data.selectedGang=ctx.g.id;if(f&&(ctx.g.fighters||[]).includes(f)){data.selectedFighter=f.id;data.view='fighter';}else{data.view='gang';data.tab=f?'vehicles':'fighters';}save();mountReturn();if(f&&(ctx.g.vehicles||[]).includes(f)){const card=[...document.querySelectorAll('[data-vehicle],[data-vehicle-id],[data-id]')].find(node=>[node.dataset.vehicle,node.dataset.vehicleId,node.dataset.id].includes(f.id));card?.scrollIntoView({block:'center'});}}
 function mountReturn(){document.querySelector('[data-cycle-finish-return]')?.remove();let d=currentDraft;if(!d){try{d=JSON.parse(sessionStorage.getItem(storageKey)||'null');}catch{}}const ctx=context(d);if(!ctx||!d?.unitId||data.selectedGang!==ctx.g.id||!['fighter','gang'].includes(data.view)||data.view==='fighter'&&data.selectedFighter!==d.unitId)return;currentDraft=d;const content=document.querySelector('.content');if(!content)return;const button=document.createElement('button');button.type='button';button.className='cycle-finish-return';button.dataset.cycleFinishReturn='';button.dataset.commandNative='';button.innerHTML='← '+L('Back to cycle finish','사이클 마무리로 돌아가기');button.onclick=()=>{button.remove();resume();};content.prepend(button);}
 function unitButton(row,textEn='View unit',textKo='유닛으로 이동'){return `<button type="button" class="cf-secondary" data-cycle-care-action="unit" data-unit-id="${E(row.fighterId||'')}">${L(textEn,textKo)} <span aria-hidden="true">→</span></button>`;}
 function open(c,g,draft){
  if(!api().participants(c).includes(g))return;const state=api().careStatus(c,g),n=Number(window.MMCampaignAutomation.cycle(c)),same=draft?.actor===actor()&&draft?.campaignId===c.id&&draft?.gangId===g.id&&draft?.cycle===n;
  remember({actor:actor(),campaignId:c.id,gangId:g.id,cycle:n,choices:same?{...draft.choices}:{}});
  const needsIncome=!((c.automationEconomy?.incomeReceipts||[]).some(row=>row.cycle===n&&(row.gangKey?row.gangKey===api().gangKey(c,g):row.gangId===g.id))),territories=(c.territories||[]).filter(row=>row.gangId===g.id),pending=state.pending||[],completed=state.completed||[],escapes=state.escapes||[];
  const careHeading=pending.length?L(`${pending.length} units need attention`,`미처리 치료 ${pending.length}명`):state.state==='complete'?L('All treatment completed','치료 모두 완료'):L('No units need treatment','치료가 필요한 유닛 없음');
  showModal(L('Finish this cycle','사이클 마무리'),`<div class="cf-screen" data-cycle-finish><div class="cf-care ${pending.length?'is-pending':'is-complete'}" data-cycle-care-state="${E(state.state)}"><div class="cf-section-heading"><span class="cf-symbol" aria-hidden="true">${pending.length?'!':'✓'}</span><div><h3>${careHeading}</h3><p>${pending.length?L('Open the pending unit or its assigned treatment below.','아래에서 남은 유닛을 확인하거나 배정된 치료를 바로 처리하세요.'):completed.length?L(`${completed.length} treated units have no pending care.`,`${completed.length}명의 치료를 처리했습니다. 남은 치료가 없습니다.`):L('Recovery and ordinary lasting injuries do not count as untreated critical injuries.','단순 회복 중 상태와 일반 지속 부상은 미처리 치료로 세지 않습니다.')}</p></div><span class="cf-badge">${pending.length?L('Pending','미완료'):L('Checked','확인 완료')}</span></div>${pending.length?`<div class="cf-unit-list">${pending.map(row=>{const f=units(g).find(f=>f.id===row.fighterId),t=(c.automationEconomy?.medicalEscorts||[]).find(t=>t.id===row.treatmentId),canAssign=row.kind==='unassigned'&&units(g).some(f=>{const result=api().actionEligibility(c,g,f,'medical');return result.allowed&&result.targets.some(target=>target.id===row.fighterId);});return `<article class="cf-unit-row" data-cycle-care-row="${E(row.fighterId||row.treatmentId)}"><div><strong data-user-text>${E(row.name||f?.name||T('Treatment record','치료 기록'))}</strong><span>${row.kind==='assigned'?L(t?.kind==='bionics'?'Bionics assigned · not yet treated':'Medical escort assigned · not yet treated',t?.kind==='bionics'?'바이오닉스 배정 · 시술 미완료':'의료 호송 배정 · 치료 미완료'):row.kind==='record-review'?L('Assigned treatment needs record review','배정된 치료 기록 확인 필요'):row.kind==='critical-damage'?L('Critical damage · repair status needs review','치명적 손상 · 수리 상태 확인 필요'):L('Critical injury · no valid medical escort assigned','치명적 부상 · 의료 호송 미배정')}</span></div><div class="cf-row-actions">${row.kind==='assigned'?`<button type="button" data-cycle-care-action="medical" data-treatment-id="${E(row.treatmentId)}">${L('Treat now','치료하기')} →</button>`:canAssign?`<button type="button" data-cycle-care-action="assign" data-unit-id="${E(row.fighterId)}">${L('Assign escort','호송자 배정')} →</button>`:row.kind==='record-review'?`<button type="button" data-cycle-care-action="review" data-treatment-id="${E(row.treatmentId)}">${L('Review record','기록 확인')} →</button>`:''}${unitButton(row)}</div></article>`;}).join('')}</div>`:completed.length?`<div class="cf-completed">${completed.map(row=>`<span>✓ <span data-user-text>${E(row.name||units(g).find(f=>f.id===row.fighterId)?.name||T('Unit','유닛'))}</span></span>`).join('')}</div>`:''}</div>${escapes.length?`<section class="cf-escape"><div class="cf-section-heading"><span class="cf-symbol" aria-hidden="true">!</span><div><h3>${L(`Post-battle capture check · ${escapes.length} pending`,`생포 후 탈출 판정 ${escapes.length}명 대기`)}</h3><p>${L('After a Captured injury result (61–62), the post-battle Escape table determines execution, ransom or escape. Core Rulebook (2026), p.86.','부상 결과 61–62 생포 이후, 전투 후 탈출 표로 처형·몸값·탈출 성공을 정하는 절차입니다. 룰북 2026, 86쪽.')}</p></div></div><div class="cf-unit-list">${escapes.map(row=>`<article class="cf-unit-row"><strong data-user-text>${E(row.name)}</strong>${unitButton(row,'View captured unit','생포 유닛 확인')}</article>`).join('')}</div></section>`:''}<section class="cf-effects"><h3>${L('What finishing does','마무리 시 반영')}</h3><p>${L('Recovery markers clear; lasting injuries remain.','회복 표시를 해제하며, 지속 부상은 유지합니다.')}</p>${needsIncome?`<p>${L('Unsettled cycle income is included automatically.','아직 정산하지 않은 사이클 수입을 함께 반영합니다.')}</p>`:''}${Number(g.tradePoints)>0?`<p>${L(`${g.tradePoints} unspent Trading Post points expire.`,`미사용 거래 포인트 ${g.tradePoints} TP가 소멸합니다.`)}</p>`:''}</section>${needsIncome&&territories.length?`<details class="cf-territories"><summary>${L('Territory income options','영토 수입 설정')} <span>${L('Optional','선택')}</span></summary><div>${territories.map(t=>`<label><span data-user-text>${E(t.name)}</span><select data-cycle-finish-income="${E(t.id)}"><option value="credits">${E(T('Credits · default','크레딧 · 기본값'))}</option>${api().territoryRule(t)?.rule_data?.income_replacement?`<option value="replacement">${E(T('Alternative benefit','대체 혜택'))}</option>`:''}<option value="skip">${E(T('Exclude · handled separately','제외 · 별도 처리'))}</option></select></label>`).join('')}</div></details>`:''}<p class="cf-error" role="alert" data-cycle-finish-error></p></div>`,T('Finish cycle','사이클 마무리 확정'),()=>{
   capture();const ctx=context();if(!ctx)throw Error(T('Records changed. Reopen cycle finish.','기록이 바뀌었습니다. 사이클 마무리를 다시 여세요.'));const fresh=api().careStatus(ctx.c,ctx.g);if(!fresh.canFinish){resume();return false;}let outcome;return window.MMCampaignAutomation.apply(ctx.c,{key:`update-roster:${n}:${api().gangKey(ctx.c,ctx.g)}`+(needsIncome?':income':''),label:'Finish cycle',gangIds:[ctx.g.id],mutate:state=>{const original=state.gangs.find(row=>row.id===ctx.g.id);outcome=api().finishCycle(state.campaign,original,currentDraft.choices);return outcome;}}).then(result=>{if(outcome&&!outcome.finished)window.MMCampaignAutomation.notify?.(T('Income is settled. Review generated benefits and Trading Post points, then finish.','수입을 정산했습니다. 생성된 영토 혜택·거래 포인트를 확인한 뒤 마무리하세요.'));return result;});
  });
  const root=document.querySelector('[data-cycle-finish]'),bg=root.closest('.modal-bg'),modal=root.closest('.modal');modal.id='campaign-cycle-finish-modal';for(const field of root.querySelectorAll('[data-cycle-finish-income]'))field.value=currentDraft.choices[field.dataset.cycleFinishIncome]||'credits';const alreadyFinished=(c.automationEconomy?.rosterFinalized||[]).some(row=>row.cycle===n&&(row.gangKey?row.gangKey===api().gangKey(c,g):row.gangId===g.id));modal.querySelector('#modal-submit').disabled=!state.canFinish||alreadyFinished;if(alreadyFinished)modal.querySelector('#modal-submit').textContent=T('Cycle already finished','이번 사이클 정리 완료');
  function capture(){for(const field of root.querySelectorAll('[data-cycle-finish-income]'))currentDraft.choices[field.dataset.cycleFinishIncome]=field.value;remember(currentDraft);}
  root.addEventListener('change',capture);root.addEventListener('click',event=>{const button=event.target.closest('[data-cycle-care-action]');if(!button)return;capture();const ctx=context();if(!ctx)return;const action=button.dataset.cycleCareAction;if(action==='unit')return openUnit(button.dataset.unitId);if(action==='assign')return assign(button.dataset.unitId);if(action==='review')return review(button.dataset.treatmentId);if(action==='medical')api().handle('medical',ctx.c,{gangId:ctx.g.id,treatmentId:button.dataset.treatmentId,incomeChoices:{...currentDraft.choices},onReturn:resume});});window.UKI18n?.refresh(modal);
 }
 function assign(targetId){const ctx=context();if(!ctx)return;const target=units(ctx.g).find(row=>row.id===targetId),eligible=units(ctx.g).filter(f=>{const result=api().actionEligibility(ctx.c,ctx.g,f,'medical');return result.allowed&&result.targets.some(row=>row.id===targetId);});if(!target||!eligible.length)return openUnit(targetId);let cleanup=()=>{};
  showModal(L('Assign a medical escort','의료 호송자 배정'),`<div class="cf-assignment"><p>${L('Choose one model to escort','치료받을 유닛')}: <strong data-user-text>${E(target.name)}</strong></p><p>${L('The escort uses one Post-cycle action. Treatment is resolved after income.','호송자는 사이클 행동 1회를 사용합니다. 실제 치료는 수입 정산 후 처리합니다.')}</p>${eligible.map(f=>`<label><input type="radio" name="finish-escort" value="${E(f.id)}"><strong data-user-text>${E(f.name)}</strong></label>`).join('')}<p role="alert" data-escort-error></p></div>`,T('Assign escort','호송자 배정'),()=>{const input=document.querySelector('[name=finish-escort]:checked');if(!input){document.querySelector('[data-escort-error]').textContent=T('Select an escort.','호송자를 선택하세요.');return false;}const current=context();if(!current)throw Error(T('Records changed.','기록이 바뀌었습니다.'));const actor=units(current.g).find(row=>row.id===input.value);return window.MMCampaignAutomation.apply(current.c,{key:api().actionKey(current.c,current.g,actor,'medical'),label:'Assign Medical Escort',gangIds:[current.g.id],mutate:state=>api().recordAction(state.campaign,state.gangs.find(row=>row.id===current.g.id),actor.id,'medical',{targetId})}).then(result=>{cleanup();setTimeout(resume,0);return result;});});document.querySelector('.modal-bg .modal').id='campaign-care-assignment-modal';cleanup=bindReturn(document.querySelector('.modal-bg'),resume);window.UKI18n?.refresh();}
 function review(treatmentId){const ctx=context();if(!ctx)return;let cleanup=()=>{};showModal(L('Review treatment record','치료 기록 확인'),`<div class="cf-assignment"><p>${L('The assigned treatment no longer matches the current unit. Closing this record spends no credits and changes no injuries or unit status.','배정된 치료가 현재 유닛 상태와 맞지 않습니다. 이 기록을 마감해도 크레딧·부상·유닛 상태는 바뀌지 않습니다.')}</p></div>`,T('Close obsolete assignment','맞지 않는 배정 기록 마감'),()=>window.MMCampaignAutomation.apply(ctx.c,{key:'close-treatment-review:'+treatmentId,label:'Review obsolete treatment',gangIds:[ctx.g.id],mutate:state=>{const g=state.gangs.find(row=>row.id===ctx.g.id),pending=api().careStatus(state.campaign,g).pending.find(row=>row.treatmentId===treatmentId&&row.kind==='record-review'),t=state.campaign.automationEconomy?.medicalEscorts?.find(row=>row.id===treatmentId&&(row.gangKey?row.gangKey===api().gangKey(state.campaign,g):row.gangId===g.id));if(!pending||!t)throw Error(T('Treatment record changed.','치료 기록이 바뀌었습니다.'));Object.assign(t,{resolved:true,resolvedAt:new Date().toISOString(),manualReview:true,result:'Obsolete assignment reviewed; no treatment applied'});}}).then(result=>{cleanup();setTimeout(resume,0);return result;}));document.querySelector('.modal-bg .modal').id='campaign-care-assignment-modal';cleanup=bindReturn(document.querySelector('.modal-bg'),resume);window.UKI18n?.refresh();}
 const priorRender=render;render=function(...args){const result=priorRender.apply(this,args);queueMicrotask(mountReturn);return result;};
 window.MMCampaignCycleFinish={open,bindReturn,resume,mountReturn};
})();
